void wdt_pat(wdt_t *w) {
    if (!w || w->expired) return;
    w->counter = w->timeout;
}
void wdt_tick(wdt_t *w) {
    if (!w || w->expired) return;
    if (w->counter == 0 || --w->counter == 0) {
        w->expired = true;
        if (w->cb) w->cb(w->ctx);   // 실제로는 시스템 리셋
    }
}
bool wdt_expired(const wdt_t *w) {
    return w ? w->expired : true;
}

bool sched_add_task(scheduler_t *s, sched_task_fn fn, uint32_t period, void *ctx) {
    if (!s || !fn || period == 0 || s->count >= SCHED_MAX) return false;
    sched_task_t *t = &s->tasks[s->count++];
    t->fn = fn; t->period = period; t->ctx = ctx; t->runs = 0;
    return true;
}
void sched_run_tick(scheduler_t *s) {
    if (!s) return;
    s->now++;
    for (size_t i = 0; i < s->count; ++i)
        if (s->now % s->tasks[i].period == 0) {
            s->tasks[i].runs++;
            s->tasks[i].fn(s->tasks[i].ctx);
        }
}

static volatile uint32_t g_primask = 0;   // 0=enable, 1=disable
uint32_t irq_save(void) {
    uint32_t prev = g_primask;
    g_primask = 1;             // disable
    return prev;
}
void irq_restore(uint32_t saved) {
    g_primask = saved;         // 이전 상태로 (중첩 안전)
}
void isr_fire(shared_t *r) {
    if (r) r->value += ISR_DELTA;
}
void atomic_add_u32(_Atomic uint32_t *c, uint32_t v) {
    atomic_fetch_add_explicit(c, v, memory_order_relaxed);
}

int pi_effective_priority(int base, const int *waiters, size_t n) {
    int eff = base;
    if (waiters)
        for (size_t i = 0; i < n; ++i)
            if (waiters[i] > eff) eff = waiters[i];
    return eff;   // 보유자를 최고 대기자로 일시 승격
}
int pcp_ceiling(const int *user_prios, size_t n) {
    if (!user_prios || n == 0) return 0;
    int c = user_prios[0];
    for (size_t i = 1; i < n; ++i)
        if (user_prios[i] > c) c = user_prios[i];
    return c;
}

static uint32_t sat_add(uint32_t a, uint32_t b) {
    uint32_t s = a + b;
    return (s < a) ? UINT32_MAX : s;   // overflow 포화
}
uint32_t irq_latency_wc(const irq_latency_t *m) {
    if (!m) return 0;
    uint32_t t = 0;
    t = sat_add(t, m->sync);
    t = sat_add(t, m->disable_window);
    t = sat_add(t, m->higher_isr);
    t = sat_add(t, m->context_save);
    t = sat_add(t, m->isr_prologue);
    return t;
}
uint32_t max_disable_window(const uint32_t *cs, size_t n) {
    if (!cs) return 0;
    uint32_t m = 0;
    for (size_t i = 0; i < n; ++i) if (cs[i] > m) m = cs[i];
    return m;
}
bool meets_deadline(uint32_t wc, uint32_t isr_exec, uint32_t deadline) {
    return sat_add(wc, isr_exec) <= deadline;
}

uint32_t reg_read(const volatile uint32_t *reg) { return reg ? *reg : 0; }
void reg_write(volatile uint32_t *reg, uint32_t val) { if (reg) *reg = val; }
void reg_set_bits(volatile uint32_t *reg, uint32_t mask) { if (reg) *reg |= mask; }
void reg_clear_bits(volatile uint32_t *reg, uint32_t mask) { if (reg) *reg &= ~mask; }
void reg_modify_field(volatile uint32_t *reg, uint32_t mask, uint32_t shift, uint32_t val) {
    if (!reg || shift >= 32) return;          // shift>=32 는 UB
    uint32_t v = *reg;
    v &= ~mask;
    v |= (val << shift) & mask;
    *reg = v;
}
bool reg_poll_flag(const volatile uint32_t *reg, uint32_t mask, uint32_t max_iters) {
    if (!reg) return false;
    for (uint32_t i = 0; i < max_iters; ++i)
        if ((*reg & mask) == mask) return true;   // volatile: 매 반복 실제 재-읽기
    return false;
}

int tw_start(timer_wheel_t *w, uint32_t delay, tw_cb cb, void *ctx) {
    if (!w || !cb || delay == 0) return -1;
    int idx = tw_alloc(w);
    if (idx < 0) return -1;                       // 풀 고갈
    uint32_t slot = (w->now + delay) % TW_SLOTS;
    w->pool[idx].active = true;
    w->pool[idx].rounds = (delay - 1) / TW_SLOTS;
    w->pool[idx].cb = cb; w->pool[idx].ctx = ctx;
    w->pool[idx].next = w->slots[slot];
    w->slots[slot] = idx;
    return idx;
}
void tw_tick(timer_wheel_t *w) {
    if (!w) return;
    w->now++;
    uint32_t s = w->now % TW_SLOTS;
    int *pp = &w->slots[s];
    while (*pp != -1) {
        int idx = *pp;
        if (w->pool[idx].rounds == 0) {
            tw_cb cb = w->pool[idx].cb; void *ctx = w->pool[idx].ctx;
            *pp = w->pool[idx].next;   // unlink (next 는 release 전에 읽음)
            tw_release(w, idx);
            cb(ctx);                   // 발동
        } else {
            w->pool[idx].rounds--;
            pp = &w->pool[idx].next;
        }
    }
}
